import {readFileSync} from 'node:fs';
import {material,input,finances,snapshot,portfolio,row,bki,reconciliationFinding,financingCase,field,activeContract,bkiFactsInput} from './builders.mjs';
export const CONTEXT_PACK_VERSION='PRESCORE-CONTEXT-RU-GOLDEN-1.0.0';
const rel=(code,effect,targetRiskCode)=>({code:`CTX-${code}`,effect,...(targetRiskCode?{targetRiskCode}:{})});
export function entries(){const out=[];const add=(n,title,mutate,expected)=>{const m=material();mutate?.(m);out.push({caseId:`CTX-RU-${String(n).padStart(3,'0')}`,revision:1,title,origin:'SYNTHETIC',asOfDate:'2026-06-30',input:input(m),expected:{invariants:true,...expected}});};
 add(1,'Healthy stable context',null,{requiredRelations:[rel('BUSINESS-PROFILE','NEUTRAL'),rel('OPERATING-TREND','NEUTRAL')],summary:{mitigatingCount:0,corroboratingCount:0}});
 const decline=m=>{m.analysis.financialAnalysisV2=finances([snapshot(2024,{2110:24000000}),snapshot(2025)]);};
 add(2,'Annual decline and recent operating decline',m=>{decline(m);m.analysis.metricsV2.operating.operatingReceiptsTrend.value=-20;},{requiredRelations:[rel('REVENUE-CORROBORATION','CORROBORATES','RISK-FIN-REVENUE-DECLINE')]});
 add(3,'Annual decline and subsequent recovery',decline,{requiredRelations:[rel('REVENUE-RECOVERY','MITIGATES','RISK-FIN-REVENUE-DECLINE')],retainedRiskCodes:['RISK-FIN-REVENUE-DECLINE']});
 const illiquid=m=>{m.analysis.financialAnalysisV2=finances([snapshot(2025,{1300:-1000000,1500:9000000})]);};
 add(4,'Financial weakness with bank cash stress',m=>{illiquid(m);m.analysis.metricsV2.liquidity.lowLiquidityDays.value=40;},{requiredRelations:[rel('LIQUIDITY-CORROBORATION','CORROBORATES','RISK-FIN-CURRENT-LIQUIDITY')]});
 add(5,'Financial weakness with complete current cash coverage',illiquid,{requiredRelations:[rel('LIQUIDITY-CURRENT-CASH','MITIGATES','RISK-FIN-CURRENT-LIQUIDITY')],retainedRiskCodes:['RISK-FIN-CURRENT-LIQUIDITY']});
 const concentrated=m=>{m.analysis.metricsV2.customers.directCustomerTop1.value=.6;};
 add(6,'Concentration without documentary contract',concentrated,{forbiddenRelations:['CTX-CONCENTRATION-CONTRACT'],retainedRiskCodes:['RISK-CF-CUSTOMER-CONCENTRATION']});
 add(7,'Concentration with active customer contract',m=>{concentrated(m);activeContract(m);},{requiredRelations:[{...rel('CONCENTRATION-CONTRACT','EXPLAINS','RISK-CF-CUSTOMER-CONCENTRATION'),confidence:'LOW'}],retainedRiskCodes:['RISK-CF-CUSTOMER-CONCENTRATION']});
 add(8,'Marketplace model not ultimate customer',m=>{m.analysis.metricsV2.customers.intermediatedOperatingShare.value=.9;},{requiredRelations:[rel('MARKETPLACE-MODEL','EXPLAINS')]});
 add(9,'Canonical seasonality eligibility',m=>{m.analysis.metricsV2.operating.seasonalityEligibility.value=1;m.analysis.metricsV2.operating.seasonalityStatus='ELIGIBLE';m.analysis.metricsV2.period.fullMonths=12;m.analysis.metricsV2.period.from='2025-07-01';m.analysis.metricsV2.monthly=Array.from({length:12},(_,i)=>({month:i<6?`2025-${String(i+7).padStart(2,'0')}`:`2026-0${i-5}`,coverage:'FULL',operatingReceipts:1500000}));},{requiredRelations:[rel('SEASONALITY-ELIGIBILITY','NEUTRAL')]});
 add(10,'Insufficient seasonality history',null,{ruleStatuses:[{code:'CTX-SEASONALITY-ELIGIBILITY',status:'INSUFFICIENT_DATA'}],forbiddenRelations:['CTX-SEASONALITY-ELIGIBILITY']});
 add(11,'Debt service with known funded portfolio',m=>{m.analysis.metricsV2.debtService.debtServiceToOperatingReceipts.value=.5;m.analysis.creditPortfolioV1=portfolio([row()]);},{requiredRelations:[rel('DEBT-SERVICE-PORTFOLIO','EXPLAINS','RISK-CF-DEBT-SERVICE-BURDEN')]});
 add(12,'Debt service with unresolved new obligation',m=>{m.analysis.metricsV2.debtService.debtServiceToOperatingReceipts.value=.5;m.analysis.creditPortfolioV1.obligationMatches.push({outcome:'AMBIGUOUS',candidateObligationIds:[]});m.analysis.creditPortfolioV1.events.push({eventId:'synthetic-new',type:'NEW_OBLIGATION_DETECTED',eventDate:'2026-06-30'});},{requiredRelations:[rel('UNRESOLVED-DEBT','REQUIRES_REVIEW')]});
 add(13,'Guarantorship separate from funded debt',m=>{m.analysis.creditPortfolioV1=portfolio([row({role:'Поручитель',guaranteeAmount:1000000})]);},{requiredRelations:[rel('CONTINGENT-GUARANTORSHIP','NEUTRAL')],forbiddenRelations:['CTX-DEBT-SERVICE-PORTFOLIO']});
 add(14,'Bank guarantee separate from funded principal',m=>{m.analysis.creditPortfolioV1=portfolio([row({product:'Банковская гарантия',guaranteeAmount:1000000})]);},{requiredRelations:[rel('CONTINGENT-BANK-GUARANTEE','NEUTRAL')],forbiddenRelations:['CTX-DEBT-SERVICE-PORTFOLIO']});
 add(15,'Historical delinquency with explicit current zero',null,{requiredRelations:[rel('BKI-CURRENT-CLEAR','MITIGATES','RISK-BKI-HISTORICAL-DELINQUENCY')],retainedRiskCodes:['RISK-BKI-HISTORICAL-DELINQUENCY']});out.at(-1).input=bkiFactsInput(0,60);
 add(16,'Current overdue and explicit historical zero',null,{requiredRelations:[rel('BKI-ZERO-HISTORY','EXPLAINS','RISK-BKI-CURRENT-OVERDUE')],retainedRiskCodes:['RISK-BKI-CURRENT-OVERDUE']});out.at(-1).input=bkiFactsInput(1000,0);
 add(17,'Stale bureau current-state limitation',m=>{m.analysis.creditHistory=bki({reportDate:'2024-01-01',obligations:[row({overdueAmount:1000,maxDelinquencyDays:60})]});},{requiredRelations:[rel('BKI-STALE','REQUIRES_REVIEW')],forbiddenRelations:['CTX-BKI-CURRENT-CLEAR']});
 add(18,'Personal owner BKI excluded',m=>{m.analysis.creditHistory=bki({subjectInn:'9900000002',relationshipToCompany:'Собственник',affectsCompanyDebt:false,obligations:[row({overdueAmount:1000,maxDelinquencyDays:60})]});},{forbiddenRelations:['CTX-BKI-CURRENT-CLEAR','CTX-BKI-ZERO-HISTORY','CTX-BKI-STALE']});
 add(19,'Same-fact accounting conflict',m=>{m.analysis.reconciliationV1.findings=[reconciliationFinding()];},{requiredRelations:[rel('RECON-CONFLICT','REQUIRES_REVIEW')]});
 add(20,'Cash-accrual relationship not conflict',m=>{m.analysis.reconciliationV1.findings=[reconciliationFinding('CASH_VS_ACCRUAL','RELATIONSHIP_OBSERVED')];},{requiredRelations:[rel('CASH-ACCRUAL','EXPLAINS')],forbiddenRelations:['CTX-RECON-CONFLICT']});
 add(21,'Missing supplied bank month',m=>{m.analysis.metricsV2.period.missingMonths=1;m.analysis.metricsV2.period.fullMonths=5;m.analysis.metricsV2.monthly[0].coverage='MISSING';},{requiredRelations:[rel('BANK-COVERAGE','REQUIRES_REVIEW')],ruleStatuses:[{code:'CTX-OPERATING-TREND',status:'INSUFFICIENT_DATA'}]});
 add(22,'Owner funding is not revenue',m=>{m.analysis.metricsV2.ownerFunding.ownerContributionAmount.value=1000000;},{requiredRelations:[rel('OWNER-FUNDING','EXPLAINS')]});
 add(23,'Factoring financing flow',m=>{m.analysis.metricsV2.financing.factoringInflow.value=1000000;},{requiredRelations:[rel('FACTORING-FLOWS','EXPLAINS')]});
 add(24,'Company age neutral calendar fact',null,{facts:[{code:'COMPANY_AGE_MONTHS',value:72,status:'KNOWN'}],requiredRelations:[rel('BUSINESS-PROFILE','NEUTRAL')]});
 add(25,'Industry neutral',null,{facts:[{code:'COMPANY_OKVED',value:'62.01'}]});
 add(26,'Region neutral',null,{facts:[{code:'COMPANY_REGION',value:'Синтетический регион'}]});
 add(27,'Exact canonical financing contract',activeContract,{requiredRelations:[rel('CASE-CONFIRMED-CONTRACT','NEUTRAL')],facts:[{code:'CASE_CONTRACT_MATCH',value:true,sourceClass:'DOCUMENT_REPORTED'}]});out.at(-1).input.financingCase=financingCase({contractReference:field('SYN-2026/1')});
 add(28,'Declared contract unmatched',null,{requiredRelations:[rel('CASE-UNMATCHED-CONTRACT','REQUIRES_REVIEW')],forbiddenRelations:['CTX-CASE-CONFIRMED-CONTRACT']});out.at(-1).input.financingCase=financingCase({contractReference:field('SYN-NOT-FOUND')});
 add(29,'Client seasonality claim is not proof',null,{requiredRelations:[rel('CASE-EXPLANATION','EXPLAINS')],forbiddenRelations:['CTX-SEASONALITY-ELIGIBILITY','CTX-REVENUE-RECOVERY']});out.at(-1).input.financingCase=financingCase({clientExplanation:field('Выручка снизилась из-за сезонности')});
 add(30,'Multiple risks and independent contexts',m=>{decline(m);m.analysis.metricsV2.operating.operatingReceiptsTrend.value=-20;concentrated(m);activeContract(m);m.analysis.reconciliationV1.findings=[reconciliationFinding()];},{requiredRelations:[rel('REVENUE-CORROBORATION','CORROBORATES'),rel('CONCENTRATION-CONTRACT','EXPLAINS'),rel('RECON-CONFLICT','REQUIRES_REVIEW')]});
 out.push({caseId:'CTX-RU-DEFECT-001',revision:1,title:'Permanent CL-RU-DEFECT-001 semantics',origin:'SYNTHETIC',asOfDate:'2026-06-30',input:bkiFactsInput(1000,0),expected:{invariants:true,requiredRelations:[rel('BKI-ZERO-HISTORY','EXPLAINS')],defectRegression:true}});
 return out;
}
export function loadContextGoldenPack(){return {version:CONTEXT_PACK_VERSION,entries:entries(),fingerprints:JSON.parse(readFileSync(new URL('./fingerprints-v1.json',import.meta.url),'utf8'))};}
